function HomeContent() {
  const searching = useSearchParams().get("view") === "search";
  const [fontsUnavailable, setFontsUnavailable] = useState(false);
  const [query, setQuery] = useState("");
  useEffect(() => {
    let active = true;
    Promise.all([document.fonts.load('900 24px "Trade Display"'), document.fonts.load('400 14px "Trade UI"')]).then((faces) => {
      if (active && faces.some((loaded) => loaded.length === 0 || loaded.some((face) => face.status !== "loaded"))) setFontsUnavailable(true);
    }).catch(() => { if (active) setFontsUnavailable(true); });
    return () => { active = false; };
  }, []);
  const rows = searching ? [132, 359, 596, 832] : [370, 544, 761];
  return <div className={styles.wrapper}>
    <section className={styles.screen} aria-label={searching ? "Original search preview" : "Original browse preview"} style={{height: searching ? 1021 : 844}}>
      <div className={styles.source} dangerouslySetInnerHTML={{__html: searching ? search : browse}} />
      <form action="/jobs" method="get" role="search" aria-label="Search electrical jobs">
        <input className={styles.searchInput} type="search" name="q" aria-label="Search current electrical jobs" value={query} onChange={(event) => setQuery(event.target.value)} placeholder={searching ? "Search for any job or problem" : "Search"} style={{left: searching ? 56.376953125 : 143.376953125, top: searching ? 22 : 42, width: searching ? 246 : 142}} />
        <button className={styles.searchSubmit} type="submit" aria-label="Submit electrical job search" style={{left:searching ? 16 : 101,top:searching ? 10 : 30,width:searching ? 40 : 42,height:39}} />
      </form>
      {!searching && <Link className={styles.hotspot} href="#web-app-navigation" aria-label="Open app menu" style={{left:22,top:32,width:44,height:37}} />}
      <Link className={styles.hotspot} href={searching ? "/jobs" : "/jobs/new"} aria-label={searching ? "Filter current electrical jobs" : "Post a job"} style={{left:331,top:searching ? 16 : 35,width:44,height:44}} />
      {!searching && <>
        <Link className={styles.hotspot} href="/jobs" aria-label="Explore electrical jobs" style={{left:15,top:153,width:159,height:162}} />
        <button type="button" className={styles.hotspot} aria-disabled="true" aria-describedby="example-note" aria-label="Construction: not currently available" title="Only electrical work is currently supported" style={{left:186,top:153,width:159,height:162}} />
        <button type="button" className={styles.hotspot} aria-disabled="true" aria-describedby="example-note" aria-label="Plumbing: not currently available" title="Only electrical work is currently supported" style={{left:357,top:153,width:159,height:162}} />
      </>}
      {rows.map((top, row) => [15,186,357].map((left, col) => <Link key={`${row}-${col}`} className={styles.hotspot} href="/jobs" aria-describedby="example-note" aria-label={`Example ${["sink installation", "furniture relocation", "electrical work"][col]} in row ${row + 1}: browse current electrical jobs`} style={{left,top,width:159,height:162}} />))}
      {(searching ? [562,797] : [332,724]).map((top) => <Link key={top} className={styles.hotspot} href="/jobs" aria-label="See all current electrical jobs" style={{left:315,top,width:74,height:44}} />)}
      {!searching && <nav className={styles.sourceNav} aria-label="Browse navigation">
        {[['/', 'Home'], ['/?view=search', 'Search'], ['/dashboard', 'Jobs'], ['/messages', 'Messages'], ['/profile', 'Account']].map(([href, label]) => <Link key={label} href={href} aria-label={label} aria-current={label === 'Home' ? 'page' : undefined} />)}
      </nav>}
    </section>
    <aside id="web-app-navigation" className={styles.adaptation} aria-label="Current web app navigation">
      <h1>Trade Marketplace</h1>
      <p id="example-note">Design preview · Listings and distances above are examples. Only electrical work is currently available; other categories are coming later.</p>
      {fontsUnavailable && <p role="status">The web font could not load. Fallback text is displayed.</p>}
      <details>
        <summary>How your job gets priced and completed</summary>
        <ol>
          <li><strong>Describe the work.</strong> Post your electrical job with photos for free.</li>
          <li><strong>Get one fixed price.</strong> Electricians provide private estimates of hours and materials, not competing quotes for you to choose between. A Trade Marketplace administrator reviews them and sets the fixed price for you to review.</li>
          <li><strong>Try the payment step.</strong> This preview records test payments only; no money is charged. Recording a test payment makes the job available for a verified electrician to claim.</li>
          <li><strong>Coordinate the visit.</strong> Claiming assigns an electrician; it does not schedule an appointment. Use the job conversation to agree on the visit.</li>
          <li><strong>Review any extra work.</strong> Extra work is described and priced separately for your approval before it proceeds.</li>
          <li><strong>Review completion.</strong> The electrician uploads a Certificate of Compliance (CoC). Review the work and certificate, then confirm completion. The job page explains its sign-off window and automatic completion conditions.</li>
        </ol>
        <p>Automatic pricing is planned; the current flow uses administrator review. <Link href="/jobs/new">Post your job</Link> or <Link href="/for-tradies">see how it works for electricians</Link>.</p>
      </details>
      <nav aria-label="Current web app"><Link href="/jobs">Find electrical work</Link><Link href="/jobs/new">Post a job</Link><Link href="/login">Log in</Link><Link href={searching ? "/" : "/?view=search"}>{searching ? "Back to Browse" : "View original Search"}</Link></nav>
    </aside>
  </div>;
}
export default function Home() { return <Suspense fallback={<p>Loading browse…</p>}><HomeContent /></Suspense>; }
